-- TEST DATA generated by scripts/simulate.mjs: replays backtest trades 2020-03-01 → 2026-10-19 (640 trades, risk 1% of pool per trade) so every screen has numbers.
-- Backtest = hypothetical. The coins were picked after seeing results; real trading will very likely do worse.
-- Needs: the migration + your manager account (create-admin.sql). Run supabase/reset-ledger-data.sql first if there are entries.
-- Creates test logins  john / john-test-123  and  dino / dino-test-123.  Wipe it all with reset-ledger-data.sql before real money.
-- Entries carry the simulated dates, so charts and lock-ups look real. If no manager exists yet it creates  raf / admin-test-123  (change it in the app!).
begin;
select public.create_first_admin('raf', 'Admin', 'admin-test-123') where not exists (select 1 from public.profiles where role = 'admin');
insert into public.sessions(token_hash, profile_id, expires_at) select encode(extensions.digest('42efbe8299ad0b0c2afa42aad9ae420d3cbe459ebb46f3ad', 'sha256'), 'hex'), id, now() + interval '1 hour' from public.profiles where role = 'admin';
select public.admin_create_user('42efbe8299ad0b0c2afa42aad9ae420d3cbe459ebb46f3ad', 'john', 'John (test)', 'john-test-123', 0.2) where not exists (select 1 from public.profiles where username = 'john');
select public.admin_create_user('42efbe8299ad0b0c2afa42aad9ae420d3cbe459ebb46f3ad', 'dino', 'Dino (test)', 'dino-test-123', 0.2) where not exists (select 1 from public.profiles where username = 'dino');
